public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s == null ? null : "";
    }
    int[] freq = new int[26];
    for (char ch : s.toCharArray()) {
        if (ch >= 'a' && ch <= 'z') {
            freq[ch - 'a']++;
        } else if (ch >= 'A' && ch <= 'Z') {
            // If uppercase letters are allowed, treat them separately or convert to lowercase.
            // Here we convert to lowercase for simplicity.
            freq[ch - 'A']++;
        } else {
            // For non-alphabetic characters, we can ignore or handle separately.
            // We'll ignore them in this implementation.
        }
    }
    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending pass
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Try all possible subset sizes up to n/2
    for (int k = 1; k <= n / 2; k++) {
        long product = (long) totalSum * k;
        if (product % n != 0) {
            continue; // target sum not integer
        }
        int target = (int) (product / n);
        // DP: dp[size][sum] indicates whether a subset of 'size' elements can sum to 'sum'
        boolean[][] dp = new boolean[k + 1][target + 1];
        dp[0][0] = true;
        for (int num : nums) {
            // Update in reverse to avoid reuse of the same element
            for (int size = k; size >= 1; size--) {
                for (int sum = target; sum >= num; sum--) {
                    if (dp[size - 1][sum - num]) {
                        dp[size][sum] = true;
                    }
                }
            }
        }
        if (dp[k][target]) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
