public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    // If k is too large, 1 << k may overflow. We assume k <= 20 for practical purposes.
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen[code] = true;
        }
    }
    for (boolean b : seen) {
        if (!b) {
            return false;
        }
    }
    return true;
}

