}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int n = s.length();
    int max = 0;
    int totalMasks = 1 << (n - 1); // number of ways to split between characters
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        int start = 0;
        boolean valid = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // split after position i
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) {
                    valid = false;
                    break;
                }
                start = i + 1;
            }
        }
        if (!valid) {
            continue;
        }
        // add the last substring
        String sub = s.substring(start);
        if (!seen.add(sub)) {
            continue;
        }
        int count = seen.size();
        if (count > max) {
            max = count;
        }
    }
    return max;
}

