public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    // Minimum possible sum is n (all 'a'), maximum is 26*n (all 'z')
    if (k < n || k > 26 * n) {
        return "";
    }
    char[] result = new char[n];
    // Start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // extra value to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can increase up to 'z'
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

