public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            bitCount += (num >> i) & 1;
        }
        if (bitCount % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0 || low > high) {
        return result;
    }
    int startLow = Math.max(low, 0);
    Queue<Long> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= startLow) {
            result.add((int) num);
        }
        if (num == 0) {
            continue; // avoid generating duplicate children for 0
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long child = num * 10 + (lastDigit - 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
        if (lastDigit < 9) {
            long child = num * 10 + (lastDigit + 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // A number that is a power of two has exactly one bit set.
    // Using the bitwise trick: n & (n - 1) == 0 for powers of two.
    return (n & (n - 1)) == 0;
}

