                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;          // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;          // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1; // diagonal
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1; // anti-diagonal

                int cellMax = Math.max(
                        Math.max(dp[i][j][0], dp[i][j][1]),
                        Math.max(dp[i][j][2], dp[i][j][3])
                );
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            } else {
                // No need to set dp values; they remain 0
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    long num = n;
    boolean negative = num < 0;
    if (negative) {
        num = -num;
    }
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (num > 0) {
        sb.append(num % 10);
        num /= 10;
        digitCount++;
        if (num > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int k = 0; k <= m + n - 2; k++) {
        if ((k & 1) == 0) { // even diagonal: traverse from bottom to top
            int row = Math.min(k, m - 1);
            int col = k - row;
            while (row >= 0 && col < n) {
                result[idx++] = mat[row][col];
                row--;
                col++;
            }
        } else { // odd diagonal: traverse from top to bottom
            int col = Math.min(k, n - 1);
            int row = k - col;
            while (row < m && col >= 0) {
                result[idx++] = mat[row][col];
                row++;
                col--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Find the largest index i such that digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // No higher permutation exists
        return -1;
    }
    // Find the largest index j > i such that digits[j] > digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the suffix starting at i + 1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert back to number
    long result;
    try {
        result = Long.parseLong(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
    if (result > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) result;
}

